<?php
header('Content-Type: application/geo+json');require dirname(__DIR__).'/bootstrap.php';if(empty($_SESSION['gh_user_id'])){http_response_code(401);echo json_encode(array('type'=>'FeatureCollection','features'=>array()));exit;}$slug=isset($_GET['city'])?$_GET['city']:'san-diego';$q=$pdo->prepare("SELECT t.id,t.title,t.started_at,t.matched_geojson,t.filtered_point_count,t.point_count FROM gh_walk_tracks t JOIN gh_cities c ON c.id=t.city_id WHERE t.user_id=? AND c.slug=? AND t.match_status='matched' AND t.matched_geojson IS NOT NULL ORDER BY t.id");$q->execute(array($_SESSION['gh_user_id'],$slug));$features=array();foreach($q as $r){$geometry=json_decode($r['matched_geojson'],true);if(!$geometry)continue;$features[]=array('type'=>'Feature','properties'=>array('id'=>(int)$r['id'],'title'=>$r['title'],'started_at'=>$r['started_at'],'raw_points'=>(int)$r['point_count'],'clean_points'=>(int)$r['filtered_point_count']),'geometry'=>$geometry);}echo json_encode(array('type'=>'FeatureCollection','features'=>$features));
